Lemma Forall_cons : forall {A} (P: A -> Prop) (g: A -> bool) x l,
  (if g x then P x else True) -> Forall P (filter g l) -> Forall P (filter g (x :: l)).
Proof. intros A P g x l Hx Hl. simpl. destruct (g x); [constructor |]; auto. Qed.

Lemma Forall_cons_side : forall {A} (P: A -> Prop) (g: A -> bool) x l,
  g x = false -> Forall P (filter g l) -> Forall P (filter g (x :: l)).
Proof. intros A P g x l Hg Hl. simpl. rewrite Hg. auto. Qed.

Lemma Forall_nil : forall {A} (P: A -> Prop) (g: A -> bool), Forall P (filter g nil).
Proof. intros. constructor. Qed.

